            // SAFETY: probe_pos is always masked with TDEFL_LZ_DICT_SIZE_MASK before reuse as a
            // chain position, so it stays within the 32768-entry m_next table.
            next_probe_pos = unsafe { *next_ptr.add(probe_pos as usize) as mz_uint };
            if next_probe_pos == 0 || {
