                dist > max_dist
            } {
                return;
            }
            probe_pos = next_probe_pos & TDEFL_LZ_DICT_SIZE_MASK as c_int as mz_uint;
            // SAFETY: probe_pos is masked to the dictionary ring and probe_pos + match_len is
            // relied on by the original unchecked indexing; the compressor invariants guarantee
            // the accessed bytes are within m_dict.
            if unsafe { *dict_ptr.add(probe_pos.wrapping_add(match_len) as usize) } as c_int
                == c0 as c_int
                // SAFETY: same proof as above for probe_pos + match_len - 1.
                && unsafe {
                    *dict_ptr.add(
                        probe_pos
                            .wrapping_add(match_len)
                            .wrapping_sub(1 as mz_uint) as usize,
                    )
                } as c_int
                    == c1 as c_int
            {
                break;
            }
        }
        if dist == 0 {
            break;
        }
        p = s;
        q = dict_ptr.offset(probe_pos as isize);
        probe_len = 0 as mz_uint;

        while max_match_len.wrapping_sub(probe_len) >= 8 {
            // SAFETY: p starts at dict_ptr + pos and advances by probe_len; the guard
            // max_match_len - probe_len >= 8 ensures this 8-byte read stays within the same
            // valid match window the original scalar loop was allowed to read.
            let pw = unsafe { ::core::ptr::read_unaligned(p.add(probe_len as usize) as *const u64) };
            // SAFETY: q starts at dict_ptr + probe_pos and advances by probe_len; with the same
            // remaining-length guard and the function's existing dictionary-window invariants,
